"""Binary Tree Cameras — greedy post-order with three node states.

0 = needs cover, 1 = covered by a child's camera, 2 = has a camera. Placing a
camera only when a child reports "needs cover" is optimal because a camera is
never more useful lower down.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def minCameraCover(self, root) -> int:
        cameras = 0

        def cover(node) -> int:
            nonlocal cameras
            if not node:
                return 1                      # null counts as covered
            left, right = cover(node.left), cover(node.right)
            if left == 0 or right == 0:
                cameras += 1
                return 2
            return 1 if left == 2 or right == 2 else 0

        return cameras + 1 if cover(root) == 0 else cameras
